<?php
session_start();
require_once __DIR__ . '/../includes/config.php';
if(empty($_SESSION['rider_logged_in'])||$_SESSION['rider_logged_in']!==true){header('Location: rider-login.php');exit;}
$riderId=(int)($_SESSION['rider_id']??0);if($riderId<1){session_destroy();header('Location: rider-login.php');exit;}
function ra_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function ra_label($v){return ucwords(str_replace('_',' ',strtolower((string)$v)));}
function ra_history($db,$oid,$status,$rid,$note){$s=$db->prepare("INSERT INTO order_status_history(order_id,status,changed_by,changed_by_role,note) VALUES(?,?,?,'delivery',?)");if($s){$s->bind_param('iiss',$oid,$status,$rid,$note);$s->execute();$s->close();}}
function ra_notify($db,$uid,$title,$message,$type,$oid){$s=$db->prepare("INSERT INTO notifications(user_id,role,title,message,type,reference_id) VALUES(?,'customer',?,?,?,?)");if($s){$s->bind_param('isssi',$uid,$title,$message,$type,$oid);$s->execute();$s->close();}}
function ra_delivery($db,$rid,$oid,$status,$column){$s=$db->prepare("SELECT id FROM rider_deliveries WHERE rider_id=? AND order_id=? ORDER BY id DESC LIMIT 1");if(!$s)return;$s->bind_param('ii',$rid,$oid);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();if($row){$s=$db->prepare("UPDATE rider_deliveries SET status=?,{$column}=NOW() WHERE id=?");if($s){$s->bind_param('si',$status,$row['id']);$s->execute();$s->close();}}else{$s=$db->prepare("INSERT INTO rider_deliveries(rider_id,order_id,status,assigned_at,accepted_at) VALUES(?,?,?,NOW(),NOW())");if($s){$s->bind_param('iis',$rid,$oid,$status);$s->execute();$s->close();}}}
$s=$conn->prepare("SELECT id,full_name,phone,status,availability_status FROM riders WHERE id=? LIMIT 1");$s->bind_param('i',$riderId);$s->execute();$rider=$s->get_result()->fetch_assoc();$s->close();if(!$rider)die('Rider account not found.');
$approved=strtolower((string)$rider['status'])==='active';$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'');$oid=(int)($_POST['order_id']??0);$conn->begin_transaction();
 try{
  if(!$approved)throw new Exception('Rider account is not approved.');
  if($oid<1||!in_array($action,['accept','picked_up','on_the_way','delivered'],true))throw new Exception('Invalid delivery request.');
  $s=$conn->prepare("SELECT id,user_id,rider_id,order_status FROM orders WHERE id=? LIMIT 1 FOR UPDATE");$s->bind_param('i',$oid);$s->execute();$o=$s->get_result()->fetch_assoc();$s->close();if(!$o)throw new Exception('Order not found.');
  $cur=strtolower((string)$o['order_status']);$assigned=(int)$o['rider_id'];
  if($action==='accept'){
   if(!in_array($cur,['preparing','ready_for_pickup'],true))throw new Exception('Only Preparing or Ready for Pickup orders can be accepted.');
   if($assigned&&$assigned!==$riderId)throw new Exception('This order is already assigned to another rider.');
   $s=$conn->prepare("UPDATE orders SET rider_id=?,order_status='rider_assigned' WHERE id=? AND (rider_id IS NULL OR rider_id=0) AND order_status IN('preparing','ready_for_pickup')");$s->bind_param('ii',$riderId,$oid);$s->execute();if($s->affected_rows!==1){$s->close();throw new Exception('This order was already taken.');}$s->close();
   ra_delivery($conn,$riderId,$oid,'accepted','accepted_at');ra_history($conn,$oid,'rider_assigned',$riderId,'Rider accepted the delivery.');ra_notify($conn,(int)$o['user_id'],'Rider assigned','A rider has accepted order #'.$oid.'. Rider information and live location are now available.','rider_assigned',$oid);$message='Delivery accepted successfully.';
   $s=$conn->prepare("UPDATE riders SET availability_status='busy' WHERE id=?");$s->bind_param('i',$riderId);$s->execute();$s->close();
  }else{
   if($assigned!==$riderId)throw new Exception('This order is not assigned to you.');
   $map=['picked_up'=>[['rider_assigned'],'Order picked up','order_picked_up','Your order #'.$oid.' has been picked up by the rider.','picked_up_at'],'on_the_way'=>[['picked_up'],'Order is on the way','out_for_delivery','Your order #'.$oid.' is now out for delivery.','started_at'],'delivered'=>[['on_the_way','picked_up'],'Order delivered','delivered','Your order #'.$oid.' has been delivered successfully.','delivered_at']];
   $cfg=$map[$action]??null;if(!$cfg||!in_array($cur,$cfg[0],true))throw new Exception('Invalid delivery stage. Current status: '.ra_label($cur).'.');
   $s=$conn->prepare("UPDATE orders SET order_status=? WHERE id=? AND rider_id=?");$s->bind_param('sii',$action,$oid,$riderId);$s->execute();if($s->affected_rows!==1){$s->close();throw new Exception('Order status could not be updated.');}$s->close();
   ra_delivery($conn,$riderId,$oid,$action,$cfg[4]);ra_history($conn,$oid,$action,$riderId,'Rider updated delivery status.');ra_notify($conn,(int)$o['user_id'],$cfg[1],$cfg[3],$cfg[2],$oid);$message='Order updated to '.ra_label($action).'.';
   if($action==='delivered'){$s=$conn->prepare("UPDATE riders SET availability_status='available' WHERE id=?");$s->bind_param('i',$riderId);$s->execute();$s->close();}
  }
  $conn->commit();
 }catch(Throwable $e){$conn->rollback();$error=$e->getMessage();}
}
$available=[];$s=$conn->prepare("SELECT o.id,o.order_number,o.user_id,o.total,o.delivery_fee,o.order_status,o.created_at,u.full_name customer_name,u.phone customer_phone FROM orders o LEFT JOIN users u ON u.id=o.user_id WHERE o.order_status IN('preparing','ready_for_pickup') AND (o.rider_id IS NULL OR o.rider_id=0) ORDER BY o.id DESC");$s->execute();$rs=$s->get_result();while($x=$rs->fetch_assoc())$available[]=$x;$s->close();
$active=[];$s=$conn->prepare("SELECT o.id,o.order_number,o.user_id,o.total,o.delivery_fee,o.order_status,o.created_at,u.full_name customer_name,u.phone customer_phone FROM orders o LEFT JOIN users u ON u.id=o.user_id WHERE o.rider_id=? AND o.order_status IN('rider_assigned','picked_up','on_the_way') ORDER BY o.id DESC");$s->bind_param('i',$riderId);$s->execute();$rs=$s->get_result();while($x=$rs->fetch_assoc())$active[]=$x;$s->close();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rider Assignment | Humsafar</title><style>body{font-family:Arial;background:#f7f8fa;margin:0;color:#222}.wrap{max-width:1000px;margin:30px auto;padding:0 18px}.card{background:#fff;border:1px solid #e5e5e5;border-radius:15px;padding:20px;margin:15px 0}.top{display:flex;justify-content:space-between;align-items:center}.badge{padding:7px 11px;border-radius:20px;background:#fff0f5;color:#d00037;font-weight:700}.success{background:#eaf9ef;color:#18703a;padding:14px;border-radius:10px}.error{background:#fff0f3;color:#b00030;padding:14px;border-radius:10px}.btn{border:0;border-radius:9px;padding:11px 15px;font-weight:700;margin:4px;cursor:pointer}.accept{background:#ef003c;color:#fff}.pickup{background:#fff1dc}.way{background:#eaf6ff}.deliver{background:#eaf9ef}.meta{color:#666;margin:8px 0}.empty{padding:35px;text-align:center;color:#777;border:1px dashed #ccc;border-radius:12px}.actions{margin-top:15px}@media(max-width:700px){.wrap{margin:15px auto}.top{align-items:flex-start;gap:10px}}</style></head><body><div class="wrap"><div class="top"><div><h1>Rider Assignment & Delivery</h1><p>Logged in as <b><?=ra_h($rider['full_name'])?></b></p></div><span class="badge"><?=ra_h(ra_label($rider['availability_status']))?></span></div><?php if($message):?><div class="success"><?=ra_h($message)?></div><?php endif;?><?php if($error):?><div class="error"><?=ra_h($error)?></div><?php endif;?><h2>New Deliveries</h2><?php if(!$approved):?><div class="empty">Your rider account is not approved.</div><?php elseif(!$available):?><div class="empty">No Preparing / Ready for Pickup orders are waiting for a rider.</div><?php else:foreach($available as $o):?><div class="card"><div class="top"><h3>Order #<?=ra_h($o['order_number'])?></h3><span class="badge"><?=ra_h(ra_label($o['order_status']))?></span></div><div class="meta">Customer: <b><?=ra_h($o['customer_name'])?></b> · <?=ra_h($o['customer_phone'])?></div><div class="meta">Total: <b>PKR <?=number_format((float)$o['total'],2)?></b> · Delivery fee: PKR <?=number_format((float)$o['delivery_fee'],2)?></div><form method="post" class="actions"><input type="hidden" name="order_id" value="<?=ra_h($o['id'])?>"><button class="btn accept" name="action" value="accept">Accept Delivery</button></form></div><?php endforeach;endif;?><h2>My Active Deliveries</h2><?php if(!$active):?><div class="empty">No active delivery.</div><?php else:foreach($active as $o):?><div class="card"><div class="top"><h3>Order #<?=ra_h($o['order_number'])?></h3><span class="badge"><?=ra_h(ra_label($o['order_status']))?></span></div><div class="meta">Customer: <b><?=ra_h($o['customer_name'])?></b> · <?=ra_h($o['customer_phone'])?></div><div class="actions"><form method="post"><input type="hidden" name="order_id" value="<?=ra_h($o['id'])?>"><?php if($o['order_status']==='rider_assigned'):?><button class="btn pickup" name="action" value="picked_up">Picked Up</button><?php elseif($o['order_status']==='picked_up'):?><button class="btn way" name="action" value="on_the_way">Start Delivery</button><?php elseif($o['order_status']==='on_the_way'):?><button class="btn deliver" name="action" value="delivered">Mark Delivered</button><?php endif;?></form></div></div><?php endforeach;endif;?></div></body></html>